(* [comment removed for export] *)
Definition XKN : list kentry :=
  map (fun c : Z * nat * Z => KWord (SA (ELit 0) (fst (fst c))) (snd (fst c)) (ELit (snd c))) XC9_CELLS
  ++ [KWord (SA (ELit 0) 6773208) 4 (EVar 4); KRange (EVar 4) 1 4194303; KImg 0x13d9c0 0x13dab0; KImg 0x13db98 0x13e340].
