       srealizes ASEGS scfg (mkCfg (@mkst fxq R' (Z_to_bv 64 ra) M' (seg_rom ASEGS)) model') K) ->
    srealizes ASEGS scfg (mkCfg (@mkst fxq R (Z_to_bv 64 0x7a198) M (seg_rom ASEGS)) model) K.
Proof.
